/*
 * A021816  Decimal expansion of 1/812.
 * https://oeis.org/A021816
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cons, easy
 * Formula:   a(n) = the nth digit (0‑based) of the decimal expansion of 1/812
 * Range:     u8 n <= 98, u16 n <= 98, u32 n <= 98, u64 n <= 98, u128 n <= 98,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* The decimal digits of 1/812 are generated by long division. */
    idx_t rem   = 1;   /* current remainder of the division 1 / 812   */
    seq_t digit = 0;   /* digit to return                                 */

    /* Re‑compute all digits up to index n on each call.
       For n ≤ 10000 this is trivial time‑wise.            */
    for (idx_t i = 0; i <= n; ++i) {
        digit = (rem * 10) / 812;    /* next digit    */
        rem   = (rem * 10) % 812;    /* update remainder */
    }

    return digit;
}
